'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const date=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.',''):'Não informado';
const company=id=>D.companies.find(x=>x.id===id),agent=id=>D.agents.find(x=>x.id===id),route=id=>D.routes.find(x=>x.id===id),loc=id=>D.locations[id];
const routeName=r=>`${loc(r.from).name} → ${loc(r.to).name}`;
const periodNames={month:'Este mês',previous:'Mês passado',days30:'Últimos 30 dias',days90:'Últimos 90 dias',year:'Este ano',custom:'Personalizado'};
const legacyPeriods={all:['2026-06-01','2026-08-31'],jun:['2026-06-01','2026-06-30'],jul:['2026-07-01','2026-07-31'],ago:['2026-08-01','2026-08-31'],empty:['2026-05-01','2026-05-31']};
const isoDay=d=>d.toISOString().slice(0,10),fullDate=d=>d?d.split('-').reverse().join('/'):'—';
function validPeriodDate(d){return /^\d{4}-\d{2}-\d{2}$/.test(d||'')&&!Number.isNaN(Date.parse(d))&&isoDay(new Date(d))===d;}
function normalizePeriod(p){const old=legacyPeriods[p.get('period')];if(old){p.set('period','custom');p.set('start',old[0]);p.set('end',old[1]);}if(!periodNames[p.get('period')||'year'])p.delete('period');if(p.get('period')!=='custom'){p.delete('start');p.delete('end');}}
function periodRange(p=Object.fromEntries(params)){
 const key=p.period||'year',end=D.cutoff,anchor=new Date(end+'T12:00:00Z');
 if(legacyPeriods[key])return {start:legacyPeriods[key][0],end:legacyPeriods[key][1],valid:true};
 if(key==='custom')return {start:p.start,end:p.end,valid:validPeriodDate(p.start)&&validPeriodDate(p.end)&&p.start<=p.end&&p.end<=D.cutoff};
 let start=end.slice(0,4)+'-01-01',until=end;
 if(key==='month')start=end.slice(0,7)+'-01';
 if(key==='previous'){start=isoDay(new Date(Date.UTC(anchor.getUTCFullYear(),anchor.getUTCMonth()-1,1)));until=isoDay(new Date(Date.UTC(anchor.getUTCFullYear(),anchor.getUTCMonth(),0)));}
 if(key==='days30'||key==='days90')start=isoDay(new Date(anchor.getTime()-((key==='days30'?30:90)-1)*86400000));
 return {start,end:until,valid:true};
}
function periodText(){const r=periodRange();return r.valid?`${periodNames[params.get('period')||'year']||'Personalizado'} · ${fullDate(r.start)} a ${fullDate(r.end)}`:'Período inválido — revise as datas';}
function periodEditor(){const r=periodRange();return `<form id="period-editor" class="period-editor" ${r.valid?'hidden':''}><label>De <input id="period-start" name="start" type="date" required max="${D.cutoff}" value="${r.valid?r.start:''}"></label><label>Até <input id="period-end" name="end" type="date" required max="${D.cutoff}" value="${r.valid?r.end:''}"></label><button class="button" type="submit">Aplicar período</button><button class="button secondary" type="button" data-action="cancel-period">Cancelar</button><small>Atalhos relativos ao corte da prévia: ${fullDate(D.cutoff)}. Início e fim incluídos.</small><p id="period-error" role="alert" hidden></p></form>`;}

function editPeriod(){const r=periodRange();$('#period-start').value=r.valid?r.start:'';$('#period-end').value=r.valid?r.end:'';$('#period-error').hidden=true;$('#period-editor').hidden=false;$('#period-start').focus();}
const periodMonths={jun:'06',jul:'07',ago:'08',empty:'05'};
const pill=(s,c='')=>`<span class="pill ${c}">${esc(s)}</span>`;
let pagePath='',params=new URLSearchParams(),scope=[],metricOps=[],metricKey='',lastFocus=null;
const viewSelections=new Map();
let savedReports=[];try{savedReports=JSON.parse(localStorage.getItem('centrix-intelligence-reports-v1')||'[]')}catch{}
function url(path,changes={}){const q=new URLSearchParams(params);if(pagePath.startsWith('fornecedores/')&&/^(rotas|locais|agentes|casos|assistentes|relatorios\/revisao)/.test(path))q.set('supplier',pagePath.split('/')[1]);if(pagePath.startsWith('rotas/')&&/^(locais|agentes|casos|assistentes)/.test(path))q.set('route',pagePath.split('/')[1]);if(pagePath.startsWith('agentes/')&&/^(casos|assistentes)/.test(path))q.set('agent',pagePath.split('/')[1]);for(const [k,v] of Object.entries(changes)){if(v===null||v==='')q.delete(k);else q.set(k,v)}return '#'+path+(q.size?'?'+q:'');}
const link=(path,label,changes={},cls='link')=>`<a class="${cls}" href="${esc(url(path,changes))}">${label}</a>`;
const action=(label,name,id='',cls='button secondary')=>`<button class="${cls}" data-action="${name}" data-id="${esc(id)}">${label}</button>`;
const panel=(title,sub,body,extra='')=>`<section class="panel"><div class="panel-head"><div><h2>${dataLabel(title)}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>${body}</section>`;
const table=(heads,body)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${dataLabel(h)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
const empty=(title='Nenhum registro neste recorte',text='Altere o período ou remova os filtros para consultar o histórico disponível.')=>`<div class="empty"><h2>${dataLabel(title)}</h2><p>${text}</p>${action('Limpar filtros','clear')}</div>`;
const tabs=(base,items,current)=>`<nav class="subnav" aria-label="Abas da ficha">${items.map(([id,name])=>link(base+'/'+id,name,{},current===id?'active':'')).join('')}</nav>`;
function heading(title,sub,extra='',before=''){return `${before}<div class="heading"><div><h1 tabindex="-1">${title}</h1><p>${sub}</p></div><div class="actions">${extra}</div></div>`;}
function filtered(extra={},ops=D.operations){const p=Object.fromEntries(params);Object.assign(p,extra);const range=periodRange(p);return ops.filter(o=>(range.valid&&o.readyPlan>=range.start&&o.readyPlan<=range.end)&&(!p.supplier||o.supplier===p.supplier)&&(!p.route||o.route===p.route)&&(!p.agent||o.agent===p.agent)&&(!p.variant||o.variant===p.variant));}
function metricCard(key,ops){const a=D.metric(key,ops);return `<div class="metric-shell"><button class="metric" data-action="metric" data-id="${key}"><span>${a.m.label}</span><b>${a.m.amount?(a.eligible.length?money(a.total):'—'):(a.rate===null?'—':a.rate+'%')}</b><small>${a.m.amount?`${a.eligible.length} de ${ops.length} com valor`:`${a.good} de ${a.eligible.length} elegíveis · base ${ops.length}`}</small><small>${!ops.length?'Sem operações neste recorte':a.excluded.length?a.excluded.length+' sem base suficiente':'Cobertura completa neste recorte'}</small><span class="metric-link">Ver casos e cálculo</span></button>${dataHelp(key)}</div>`;}
function metrics(keys,ops){return `<div class="metrics">${keys.map(k=>metricCard(k,ops)).join('')}</div>`;}
function commonContext(){const fixed=pagePath.startsWith('fornecedores/')?pagePath.split('/')[1]:'';return `<div class="context"><label>Período <select id="period" aria-label="Período">${Object.entries(periodNames).map(([v,t])=>`<option value="${v}" ${(params.get('period')||'year')===v?'selected':''}>${t}</option>`).join('')}</select></label><span class="period-range">${periodRange().valid?fullDate(periodRange().start)+' a '+fullDate(periodRange().end):'Revise as datas'}</span>${params.get('period')==='custom'?action('Editar datas','edit-period','','text-button'):''}${action('Filtrar','filters','','text-button')}${['supplier','route','agent','variant'].filter(k=>params.get(k)).map(k=>`<button class="filter-chip" data-action="remove-filter" data-id="${k}" aria-label="Remover filtro ${k}">${esc(k==='supplier'?company(params.get(k))?.name:k==='route'?routeName(route(params.get(k))):k==='agent'?agent(params.get(k))?.name:params.get(k)==='direto'?'Serviço direto':'Via Singapura')} ×</button>`).join('')}<span class="base">Base: compromisso de prontidão no período${dataHelp("ready")}${fixed?' · '+esc(company(fixed)?.name||''):''}</span></div>${periodEditor()}<div id="filters-panel" class="filters" hidden>${[['supplier','Fornecedor',D.companies],['route','Rota',D.routes.map(r=>({...r,name:routeName(r)}))],['agent','Agente',D.agents]].map(([key,label,values])=>`<label>${label}<select data-filter="${key}" aria-label="${label}"><option value="">Todos</option>${values.map(x=>`<option value="${x.id}" ${(key==='supplier'&&fixed?fixed:params.get(key))===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`).join('')}</div>`;}
function moduleNav(){const section=pagePath.split('/')[0];$('#module-nav').innerHTML=[['performance','Performance',['performance']],['fornecedores','Parceiros',['fornecedores','agentes','casos']],['rotas','Rotas e locais',['rotas','locais']],['relatorios','Relatórios',['relatorios']],['assistentes/biblioteca','Assistentes',['assistentes']]].map(([path,name,group])=>link(path,name,path.startsWith('assistentes')?{}:{variant:null},group.includes(section)?'active':'')).join('');}
function partnerToggle(type){return `<nav class="section-toggle" aria-label="Tipos de parceiro">${link('fornecedores','Fornecedores',{},type==='fornecedores'?'active':'')}${link('agentes','Agentes de carga',{},type==='agentes'?'active':'')}</nav>`;}
function routeToggle(type){return `<nav class="section-toggle" aria-label="Rotas e locais">${link('rotas','Rotas',{},type==='rotas'?'active':'')}${link('locais','Locais',{},type==='locais'?'active':'')}</nav>`;}
function operationsTable(ops){if(!ops.length)return empty();return table(['Entrega / mercadoria','Fornecedor / rota','Prontidão','Chegada ao porto','Destino final'],ops.map(o=>`<tr><td>${link('casos/'+o.id,`<b>${o.po}</b>`)}<small>${o.cargo} · ${o.sku}</small><small>${o.id} · 1.000 un. pedidas</small></td><td>${link('fornecedores/'+o.supplier+'/resumo',esc(company(o.supplier).name),{},'')}<small>${link('rotas/'+o.route+'/resumo',routeName(route(o.route)),{},'')}</small><small>${link('agentes/'+o.agent+'/resumo',agent(o.agent).name,{},'')}</small></td><td class="nowrap">${date(o.ready)}<small>Prometida: ${date(o.readyPlan)}</small>${o.ready?pill(o.ready>o.readyPlan?`+${D.days(o.readyPlan,o.ready)} d`:'No prazo',o.ready>o.readyPlan?'warn':'good'):pill('Sem confirmação')}</td><td class="nowrap">${date(o.arrive||o.arriveForecast)} ${pill(o.arrive?'Realizado':'Previsto',o.arrive?'':'purple')}<small>${loc(route(o.route).to).name} · 1º ETA ${date(o.arrivePlan)}</small></td><td class="nowrap">${date(o.final||o.finalForecast)} ${pill(o.final?'Realizado':'Previsto',o.final?'':'purple')}<small>Joinville · ${o.received===null?'Recebimento sem quantidade':o.received+' un. recebidas'}</small></td></tr>`).join(''));}
function evolution(ops){return panel('Como o desempenho evolui','Coortes pelo compromisso de prontidão. Clique no mês para ver os casos.',`<div class="trend">${[['jun','Junho'],['jul','Julho'],['ago','Agosto']].map(([k,label])=>{const group=ops.filter(o=>o.readyPlan.slice(5,7)===periodMonths[k]),a=D.metric('ready',group),b=D.metric('port',group);return `<button data-action="month" data-id="${k}"><span>${label}</span><div class="track"><span class="bar" style="height:${a.rate||0}%"></span><span class="bar alt" style="height:${b.rate||0}%"></span></div><b class="rate">${a.rate===null?'—':a.rate+'%'}</b><small>Prontidão ${a.good}/${a.eligible.length}</small><small>Porto ${b.good}/${b.eligible.length} · ${b.rate===null?'—':b.rate+'%'}</small></button>`}).join('')}</div><div class="legend"><span><i></i>Prontidão no prazo</span><span><i class="alt"></i>Chegada ao porto no prazo</span></div><div class="note" style="margin:0 24px 22px">Comparação descritiva. Agosto inclui operações ainda em transporte; amostras e variantes diferem. Não comprova uma melhora sustentada.</div>`);}
function stagePanel(ops){return panel('Onde os tempos excedem o previsto','Dias corridos por trecho concluído; cada linha abre a base.',D.stages.map(s=>{const e=ops.filter(o=>o[s.from]&&o[s.to]),bad=e.filter(o=>D.days(o[s.from],o[s.to])>s.plan(o));return `<button class="stage-row" data-action="stage" data-id="${s.id}"><div>${s.label}<small>${e.length} de ${ops.length} com marcos</small></div><div class="track"><div class="fill" style="width:${e.length?bad.length/e.length*100:0}%"></div></div><b>${bad.length}/${e.length}<small>acima do previsto</small></b></button>`}).join(''));}
function supplierList(){scope=filtered();return partnerToggle('fornecedores')+heading('Fornecedores','Entenda o fornecimento, acompanhe as entregas e prepare a próxima conversa.')+`<div class="search"><input id="search" aria-label="Buscar fornecedor" placeholder="Buscar fornecedor, país ou cidade"><small>Fornecedor = exportador da mercadoria</small></div><section class="panel" id="supplier-results">${supplierRows('')}</section><div class="note spaced">Prontidão, documentação e recebimento são dimensões distintas. O atraso no transporte aparece como resultado da cadeia, sem atribuição automática ao fornecedor.</div>`;}
function supplierRows(q){const list=D.companies.filter(c=>(!params.get('supplier')||c.id===params.get('supplier'))&&`${c.name} ${c.country} ${c.city}`.toLowerCase().includes(q.toLowerCase()));return list.length?table(['Fornecedor / origem','Entregas na base','Prontidão no prazo','Frete contratado',''],list.map(c=>{const ops=scope.filter(o=>o.supplier===c.id),m=D.metric('ready',ops),f=D.metric('freight',ops);return `<tr><td>${link('fornecedores/'+c.id+'/resumo',`<b>${esc(c.name)}</b>`,{supplier:null})}<small>${c.city}, ${c.country} · Exportador</small></td><td><b>${ops.length}</b><small>${ops.filter(o=>o.final).length} com entrega final confirmada</small></td><td><b>${m.rate===null?'—':m.rate+'%'}</b><small>${m.good}/${m.eligible.length} elegíveis · base ${ops.length}</small></td><td>${f.eligible.length?money(f.total):'—'}<small>Internacional · USD · ${f.eligible.length}/${ops.length}</small></td><td>${link('fornecedores/'+c.id+'/resumo','Abrir ficha',{supplier:null})}</td></tr>`}).join('')):empty('Nenhum fornecedor encontrado','Tente buscar por Eastbridge, Nordwerk ou país.');}
function supplierDetail(id,tab='resumo'){const c=company(id);if(!c)return empty('Fornecedor não encontrado');scope=filtered({supplier:id});const intro=heading(esc(c.name),`${c.city}, ${c.country} · Fornecedor / exportador da mercadoria`,link('relatorios/revisao','Preparar revisão',{supplier:id},'button')+link('assistentes/fornecedor/resumo','Analisar com minha IA',{supplier:id},'button secondary')+action('Identidade cadastral','identity',id),link('fornecedores','‹ Fornecedores',{supplier:null},'back'));const nav=tabs('fornecedores/'+id,[['resumo','Resumo'],['entregas','Entregas'],['rotas','Rotas'],['qualidade','Qualidade']],tab);
  let body='';if(tab==='resumo'){body=metrics(['ready','port','freight','cargo'],scope)+`<div class="split">${evolution(scope)}${panel('Pontos para revisar','Ocorrências observadas, com evidência e lacunas.',[['ready','Compromisso de prontidão'],['docs','Primeira versão documental'],['quantity','Quantidade recebida'],['condition','Condição da mercadoria']].map(([key,label])=>{const a=D.metric(key,scope);return `<div class="row"><div><button class="link" data-action="metric" data-id="${key}">${label}</button><small>${a.eligible.length} registros elegíveis · ${a.excluded.length} sem base</small></div><span class="value">${a.eligible.length-a.good} ${a.eligible.length-a.good===1?'desvio':'desvios'}</span></div>`}).join(''),link('fornecedores/'+id+'/qualidade','Ver qualidade'))}</div><div class="spaced">${panel('Entregas que explicam o período',`${scope.length} POs e ${scope.length} embarques distintos nesta demonstração.`,operationsTable(scope),link('fornecedores/'+id+'/entregas','Ver todas'))}</div>`;}
  else if(tab==='entregas'){body=`<div class="search"><label>Situação <select id="delivery-status" aria-label="Situação das entregas"><option value="all">Todas as entregas</option><option value="active">Em andamento</option><option value="done">Concluídas no destino final</option></select></label><small>Porto de destino e entrega final têm marcos próprios.</small></div><section class="panel" id="delivery-rows">${operationsTable(scope)}</section>`;}
  else if(tab==='rotas')body=routeCards(scope)+`<div class="note spaced">Os percursos compartilham a identidade de Configurações. Coleta, conexão e destino final completam somente os cenários cobertos por esta demonstração.</div>`;
  else if(tab==='qualidade')body=`<div class="grid-two">${['ready','docs','quantity','condition'].map(key=>{const a=D.metric(key,scope);return `<section class="panel quality-card"><div class="result"><h2>${dataLabel(a.m.label,key)}</h2><b>${a.rate===null?'—':a.rate+'%'}</b></div><small>${a.good} de ${a.eligible.length} elegíveis · base ${scope.length}</small><p>${a.m.definition}</p><p>Fonte: ${a.m.source}. ${a.excluded.length} sem base suficiente.</p>${action('Abrir registros e evidências','metric',key)}</section>`}).join('')}</div><div class="note spaced">Avaria e falta no recebimento pedem apuração. No caso demonstrativo de embalagem amassada, o responsável ainda não foi determinado.</div>`;
  else body=empty('Aba não encontrada');return intro+nav+body;}
function routeCards(ops){return panel('Percursos utilizados','Abra a rota para consultar variantes, trechos e locais.',D.routes.filter(r=>ops.some(o=>o.route===r.id)).map(r=>{const group=ops.filter(o=>o.route===r.id);return `<div class="row"><div>${link('rotas/'+r.id+'/resumo',`<b>${routeName(r)}</b>`)}<p>${r.collection?loc(r.collection).name:'Coleta a definir'} → ${r.final?loc(r.final).name:'Destino final a definir'}</p><small>${r.equipment} · ${new Set(group.map(o=>o.variant)).size} variante(s)</small></div><span class="value">${group.length}<small>embarques</small></span></div>`}).join('')||empty());}
function journey(r,variant='direto'){const points=[r.collection,r.from,...(variant==='conexao'?['singapore']:[]),r.to,r.final].filter(Boolean);return `<div class="journey">${points.map((p,i)=>`<div class="stop"><span class="dot"></span>${link('locais/'+p+'/resumo',loc(p).name,{},'')}<small>${loc(p).code||'Sem código externo'}</small><small>${i===0&&r.collection?'Coleta':p===r.final?'Destino final':p===r.to?'Chegada internacional':p==='singapore'?'Conexão':'Embarque'}</small></div>`).join('')}</div><div class="journey-label">${dataHelp("route")}${r.mode} · ${r.equipment} · ${variant==='conexao'?'Variante via Singapura':'Variante direta'}${!r.final?' · Entrega final sem definição no cadastro':''}</div>`;}
function routesList(){scope=filtered();return routeToggle('rotas')+heading('Rotas','Do local de coleta ao destino final, com o trecho internacional identificado.')+panel('Seu catálogo de percursos','Identidades reutilizadas de Configurações; contagens calculadas nesta base.',D.routes.map(r=>`<div class="row"><div>${link('rotas/'+r.id+'/resumo',`<b>${routeName(r)}</b>`)}<p>${r.mode} · ${r.equipment}</p><small>${r.collection?loc(r.collection).name:'Coleta não definida'} → ${r.final?loc(r.final).name:'Destino final não definido'}</small></div><div class="value">${scope.filter(o=>o.route===r.id).length}<small>embarques no recorte</small></div></div>`).join(''));}
function routeDetail(id,tab='resumo'){const r=route(id);if(!r)return empty('Rota não encontrada');scope=filtered({route:id});const variants=[...new Set(scope.map(o=>o.variant))];const v=params.get('variant')||'direto';const intro=heading(routeName(r),`${r.mode} · ${r.equipment} · Corredor internacional cadastrado`,action('Identidade cadastral','route-identity',id),link('rotas','‹ Rotas',{},'back'))+tabs('rotas/'+id,[['resumo','Resumo'],['etapas','Etapas e locais'],['operacoes','Operações'],['agentes','Agentes'],['alternativas','Alternativas']],tab);
 let body=journey(r,v)+`<div class="search spaced"><label>Variante <select id="variant" aria-label="Variante da rota"><option value="">Todas · percurso direto ilustrado</option><option value="direto" ${params.get('variant')==='direto'?'selected':''}>Serviço direto</option>${id==='ningbo'?`<option value="conexao" ${params.get('variant')==='conexao'?'selected':''}>Via Singapura</option>`:''}</select></label><small>${scope.length} operações · ${variants.length} variante(s) no recorte</small></div>`;
 if(!scope.length)body+=empty('Sem histórico neste recorte','A identidade da rota continua disponível. O cadastro por si só não cria métricas.');
 else if(tab==='resumo')body+=metrics(['port','final','freight','audit'],scope)+`<div class="split">${stagePanel(scope)}${panel('Variantes deste corredor','Comparações preservam o serviço e o tamanho da amostra.',variants.map(x=>{const g=scope.filter(o=>o.variant===x),done=g.filter(o=>o.collect&&o.final);const durations=done.map(o=>D.days(o.collect,o.final));return `<div class="row"><div>${link('rotas/'+id+'/operacoes',x==='direto'?'Serviço direto':'Via Singapura',{variant:x})}<p>${g.length} embarques · ${done.length} com ponta a ponta</p><small>${durations.length?`Coleta → Joinville: ${Math.min(...durations)}–${Math.max(...durations)} dias realizados`:'Sem entrega final confirmada'}</small></div></div>`}).join('')+'<div class="pad muted">Duração calculada por operação completa. Não é soma de médias de amostras diferentes.</div>')}</div>`;
 else if(tab==='etapas')body+=stagePanel(scope)+connectionPanel(scope)+`<div class="note spaced">Cada trecho compara seus próprios marcos. Tempo no porto não comprova congestionamento ou responsabilidade do terminal. Os locais do percurso abrem suas passagens.</div>`;
 else if(tab==='operacoes')body+=`<section class="panel">${operationsTable(scope)}</section>`;
 else if(tab==='agentes')body+=agentRows(scope);
 else if(tab==='alternativas')body+=panel('Alternativas para avaliar','Planejado · sem simulação de preço ou oferta atual.',`<div class="pad"><p>Revisar coleta e porto alternativo exige saída, espaço, trânsito e trecho terrestre comparáveis.</p><div class="note spaced">O histórico é descritivo. Não há recomendação de trocar de rota sem confirmar condições atuais e necessidade do negócio.</div>${id==='ningbo'?'<div class="spaced">'+link('rotas/shanghai/resumo','Consultar histórico via Shanghai e Santos',{variant:null})+'</div>':''}</div>`);
 return intro+body;}
function localPassages(id,ops){return ops.flatMap(o=>{const r=route(o.route);let entry=null,out=null,label='',source='';if(id===r.collection){entry=o.ready;out=o.collect;label='Prontidão → coleta';source='Confirmação do exportador + recibo de coleta'}else if(id===r.from){entry=o.collect;out=o.depart;label='Coleta → embarque (inclui acesso ao porto)';source='Coleta + saída do navio'}else if(id===r.to){entry=o.arrive;out=o.gate;label='Chegada → gate out';source='Tracking + gate out'}else if(id==='singapore'&&o.variant==='conexao'){entry=o.connectionIn;out=o.connectionOut;label='Entrada → saída da conexão';source='Eventos de conexão'}else if(id===r.final){entry=o.final;label='Entrega final';source='Comprovante de entrega'}else return [];return [{id:o.id+'-'+id,operation:o,entry,out,label,source}];});}
function connectionPanel(ops){const group=ops.filter(o=>o.variant==='conexao');if(!group.length)return '';return `<div class="spaced">${panel('Dentro do trânsito via Singapura','Subtrechos da variante com conexão. Já estão contidos no trânsito internacional acima.',D.connectionStages.map(s=>{const e=group.filter(o=>o[s.from]&&o[s.to]),dur=e.map(o=>D.days(o[s.from],o[s.to]));return `<button class="stage-row" data-action="stage" data-id="${s.id}"><div>${s.label}<small>${e.length}/${group.length} com marcos · previsto ${s.plan()} d</small></div><div class="muted">${dur.length?Math.min(...dur)+'–'+Math.max(...dur)+' d realizados':'Sem intervalo realizado'}</div><b>Ver casos</b></button>`}).join(''),link('locais/singapore/resumo','Abrir Singapura'))}</div>`;}
function localList(){scope=filtered();return routeToggle('locais')+heading('Locais','Portos, conexões e pontos de coleta ou entrega envolvidos nos seus percursos.')+panel('Locais da operação','Histórico da Aurora; não é avaliação geral de cada porto.',table(['Local','Identificação','Passagens registradas',''],Object.entries(D.locations).map(([id,l])=>{const passes=localPassages(id,scope);return `<tr><td>${link('locais/'+id+'/resumo',`<b>${l.name}</b>`)}<small>${l.country}</small></td><td>${l.type}<small>${l.code||'Sem código externo'}</small></td><td>${passes.filter(p=>p.entry).length}<small>${passes.filter(p=>!p.entry).length} sem evento de entrada</small></td><td>${link('locais/'+id+'/resumo','Abrir local')}</td></tr>`}).join('')));}
function localDetail(id,tab='resumo'){const l=loc(id);if(!l)return empty('Local não encontrado');const all=filtered(),passes=localPassages(id,all);scope=passes.map(p=>p.operation);const completed=passes.filter(p=>p.entry&&p.out),entered=passes.filter(p=>p.entry),durations=completed.map(p=>D.days(p.entry,p.out));const intro=heading(l.name,`${l.type} · ${l.code||'Sem código externo'} · ${l.country}`,action('Identidade do local','local-identity',id),link('locais','‹ Locais',{},'back'))+tabs('locais/'+id,[['resumo','Resumo'],['movimentacoes','Movimentações'],['rotas','Rotas']],tab);
 const movements=()=>table(['Passagem / entrega','Intervalo observado','Entrada realizada','Saída realizada'],passes.map(p=>`<tr><td>${link('casos/'+p.operation.id,p.operation.po)}<small>${p.id}</small><small>${link('agentes/'+p.operation.agent+'/resumo',agent(p.operation.agent).name,{},'')}</small></td><td>${p.label}<small>${id==='aurora-factory'?'Evento de recebimento':p.entry&&p.out?D.days(p.entry,p.out)+' dias corridos':'Intervalo incompleto'}</small><small>${p.source} · demo</small></td><td>${date(p.entry)}<small>${p.entry?'Evento realizado':'Sem evento confirmado'}</small></td><td>${p.out?date(p.out):id==='aurora-factory'?'Não se aplica':'Ainda não confirmada'}</td></tr>`).join(''));
 let body='';if(tab==='resumo')body=`<div class="metrics"><button class="metric" data-action="local-moves" data-id="${id}"><span>Passagens registradas</span><b>${entered.length}</b><small>${passes.length} previstas no percurso</small><span class="metric-link">Abrir movimentações</span></button><button class="metric" data-action="local-moves" data-id="${id}"><span>Embarques distintos com entrada</span><b>${new Set(entered.map(p=>p.operation.id)).size}</b><small>IDs únicos neste local</small><span class="metric-link">Consultar casos</span></button><button class="metric" data-action="local-moves" data-id="${id}"><span>Intervalo realizado</span><b>${durations.length?Math.min(...durations)+'–'+Math.max(...durations)+' d':'—'}</b><small>${id==='aurora-factory'?'Não se aplica: entrega tem evento único':completed.length+'/'+passes.length+' com dois marcos'}</small><span class="metric-link">Ver eventos e fontes</span></button><div class="metric"><span>Papel no percurso</span><b style="font-size:21px">${id==='aurora-factory'?'Destino final':l.type.includes('Porto')?'Porto':'Local'}</b><small>${passes[0]?.label||'Sem passagem conhecida'}</small></div></div><div class="note">${l.type.includes('Porto')?'Estes tempos refletem as operações da Aurora. Documentação, desembaraço, armador e cliente podem participar do intervalo; não há causa atribuída ao porto.':'Os marcos apresentados correspondem a este local. A chegada internacional permanece separada da entrega final.'}</div><div class="spaced">${panel('Passagens e fontes','Cada passagem mantém a identidade da operação e seus eventos.',passes.length?movements():empty(),link('locais/'+id+'/movimentacoes','Ver movimentações'))}</div>`;
 else if(tab==='movimentacoes')body=panel('Movimentações','Datas realizadas; campo ausente não significa passagem concluída.',passes.length?movements():empty());else if(tab==='rotas')body=routeCards(scope);return intro+body;}
function agentRows(ops){return panel('Agentes neste recorte','Preferência cadastral e desempenho observado são dimensões distintas.',D.agents.map(a=>{const group=ops.filter(o=>o.agent===a.id),m=D.metric('port',group),audit=D.metric('audit',group);return `<div class="row"><div>${link('agentes/'+a.id+'/resumo',`<b>${a.name}</b>`)}<p>${group.length} contratações · ${m.good}/${m.eligible.length} chegadas no prazo</p><small>${audit.eligible.length} conferências concluídas de ${group.length} operações</small></div>${a.preferred?pill('Preferido da empresa','purple'):pill('Sem preferência')}</div>`}).join(''));}
function agentsList(){scope=filtered();return partnerToggle('agentes')+heading('Agentes de carga','Conecte o que foi contratado, como foi executado e o que foi cobrado.')+agentRows(scope);}
function agentDetail(id,tab='resumo'){const a=agent(id);if(!a)return empty('Agente não encontrado');scope=filtered({agent:id});const intro=heading(a.name,`Agente de carga · ${a.contact} · ${a.preferred?'Preferido no cadastro da empresa':'Sem preferência cadastral'}`,action('Identidade cadastral','agent-identity',id),link('agentes','‹ Agentes de carga',{},'back'))+tabs('agentes/'+id,[['resumo','Resumo'],['historico','Histórico'],['rotas','Rotas'],['auditoria','Auditoria']],tab);
 let body='';if(tab==='resumo')body=metrics(['port','final','audit','freight'],scope)+`<div class="split">${panel('Da contratação à conferência','Um mesmo histórico para revisar o relacionamento.',`<div class="row"><div><b>Contratação</b><p>${scope.length} propostas aceitas · frete internacional em USD</p><small>Sem base de propostas perdidas ou não respondidas.</small></div>${link('agentes/'+id+'/historico','Ver')}</div><div class="row"><div><b>Execução</b><p>${scope.filter(o=>o.arrive).length} chegadas internacionais confirmadas</p><small>Desvio observado não determina responsabilidade.</small></div>${action('Ver casos','metric','port','text-button')}</div><div class="row"><div><b>Auditoria financeira</b><p>${D.metric('audit',scope).eligible.length} conferências concluídas</p><small>Diferença fundamentada não é valor recuperado.</small></div>${link('agentes/'+id+'/auditoria','Ver')}</div>`)}${stagePanel(scope)}</div>`;
 else if(tab==='historico')body=panel('Histórico conectado','Condições aceitas, marcos realizados e conferência por operação.',table(['Entrega / contratação','Execução','Conferência'],scope.map(o=>`<tr><td>${link('casos/'+o.id,o.po)}<small>COT-${o.id} · proposta aceita</small><small>${money(o.freight)} · ${route(o.route).equipment}</small></td><td>${date(o.arrive||o.arriveForecast)} · ${o.arrive?'chegada realizada':'chegada prevista'}<small>${link('rotas/'+o.route+'/resumo',routeName(route(o.route)),{},'')}</small></td><td>${D.metrics.audit.value(o)}<small>${link('casos/'+o.id,'Contratado → realizado → auditoria',{},'')}</small></td></tr>`).join('')));
 else if(tab==='rotas')body=routeCards(scope);else if(tab==='auditoria')body=metrics(['audit','freight','port','final'],scope)+panel('Auditoria de frete e de performance','Resultados financeiros e desvios de prazo apresentados separadamente.',table(['Caso','Frete / cobrança','Performance / responsabilidade',''],scope.map(o=>`<tr><td>${link('casos/'+o.id,o.po)}<small>${o.id}</small></td><td>${D.metrics.audit.value(o)}<small>${o.audit==='divergencia'?'Taxas de origem · USD 195 em esclarecimento':'Escopo financeiro identificado no caso'}</small></td><td>${o.arrive?Math.max(0,D.days(o.arrivePlan,o.arrive))+' d após o 1º ETA':'Sem chegada realizada'}<small>${o.arrive&&o.arrive>o.arrivePlan?'Causa do transporte não apurada':'Sem atribuição automática ao agente'}</small></td><td>${action('Abrir evidências','audit',o.id,'text-button')}</td></tr>`).join('')));return intro+body;}
function caseDetail(id){const o=D.operations.find(o=>o.id===id);if(!o)return empty('Caso não encontrado');scope=[o];const r=route(o.route);const excluded=!filtered().includes(o);return heading(`${o.po} · ${o.cargo}`,`${o.id} · ${o.sku} · 1.000 unidades pedidas`,action('Abrir fontes','sources',id),`<button class="back" data-action="back">‹ Voltar à análise</button>`)+(excluded?'<div class="note spaced">Você abriu um caso fora dos filtros atuais por um link direto. A ficha mostra somente esta operação; ao voltar, o recorte anterior permanece.</div>':'')+`<div class="panel"><div class="panel-head"><div><div class="overline">Entrega de mercadoria</div><h2>${link('fornecedores/'+o.supplier+'/resumo',company(o.supplier).name,{},'')}</h2><p>${link('agentes/'+o.agent+'/resumo',agent(o.agent).name,{},'')} · ${link('rotas/'+o.route+'/resumo',routeName(r),{variant:o.variant},'')}</p></div>${pill(o.final?'Entrega final confirmada':'Em andamento',o.final?'good':'purple')}</div>${journey(r,o.variant)}${[['Prontidão','readyPlan','ready',null],['Coleta','collectPlan','collect',null],['Saída internacional','departPlan','depart',null],['Chegada a '+loc(r.to).name,'arrivePlan','arrive','arriveForecast'],['Entrega em Joinville','finalPlan','final','finalForecast']].map(([label,p,a,f])=>`<div class="timeline-row"><strong>${dataLabel(label,{ready:"ready",collect:"collect",depart:"port",arrive:"port",final:"final"}[a])}</strong><div><small>Compromisso original</small><b>${date(o[p])}</b></div><div><small>${o[a]?'Realizado':f?'Previsão atual':'Realizado'}</small><b>${date(o[a]||(f?o[f]:null))}</b> ${o[a]&&o[a]>o[p]?pill('+'+D.days(o[p],o[a])+' d','warn'):!o[a]?pill(f?'Previsto':'Sem confirmação','purple'):pill('No prazo','good')}</div></div>`).join('')}</div><div class="grid-two spaced">${panel('Fornecimento e recebimento','Responsabilidade exige evidência específica.',`<div class="pad"><p><b>Documentação:</b>${dataHelp("docs")} ${D.metrics.docs.value(o)}</p><p class="spaced"><b>Quantidade:</b>${dataHelp("quantity")} ${D.metrics.quantity.value(o)}</p><p class="spaced"><b>Condição:</b>${dataHelp("condition")} ${D.metrics.condition.value(o)}</p><div class="note spaced">${o.docs==='corrigida'?'O checklist registra correção de packing list pelo exportador. Não comprova que essa correção causou atraso no transporte.':'Os registros confirmam apenas a dimensão observada; não há score consolidado.'}${o.condition==='avaria'?' Embalagem amassada no recebimento; origem da avaria em apuração.':''}</div></div>`)}${panel('Contratação e auditoria','Mesmo escopo e moeda na comparação.',`<div class="pad"><p>COT-${o.id} · ${money(o.freight)} de frete internacional contratado.</p><p class="spaced"><b>${D.metrics.audit.value(o)}</b></p><small>Taxas de origem e performance detalhadas separadamente.</small><div class="actions spaced">${action('Conferir evidências','audit',o.id)}${link('agentes/'+o.agent+'/auditoria','Histórico do agente')}</div></div>`)}</div><div class="spaced">${stagePanel([o])}</div>`;}
function performance(){scope=filtered();const total=scope.length,active=scope.filter(o=>!o.final).length;return heading('Performance','Localize os desvios da cadeia e investigue os parceiros e etapas envolvidos.',link('relatorios','Preparar relatório',{},'button'))+`<div class="search"><small>${total} embarques distintos no recorte · ${total-active} com entrega final · ${active} em andamento</small></div>`+metrics(['ready','port','final','freight'],scope)+`<div class="split">${stagePanel(scope)}${evolution(scope)}</div><div class="grid-two spaced">${panel('Fornecimento por parceiro','Prontidão original e documentação, sem score.',D.companies.map(c=>{const ops=scope.filter(o=>o.supplier===c.id),a=D.metric('ready',ops),b=D.metric('docs',ops);return `<div class="row"><div>${link('fornecedores/'+c.id+'/resumo',c.name,{supplier:null})}<p>Prontidão: ${a.good}/${a.eligible.length} no prazo</p><small>Documentação: ${b.good}/${b.eligible.length} sem correção · base ${ops.length}</small></div></div>`}).join(''))}${routeCards(scope)}</div><div class="spaced">${panel('Casos que compõem esta análise','Métricas e relatórios usam estas mesmas operações.',operationsTable(scope))}</div>`;}
function reportLibrary(){scope=filtered();return heading('Relatórios','Prepare uma revisão com período, fontes e casos que sustentam a conversa.')+`<div class="grid-two">${panel('Revisão de fornecedor','Disponível nesta prévia',`<div class="pad"><p>Prontidão, documentação, recebimento, evolução e pauta de melhoria.</p><div class="actions spaced">${D.companies.map(c=>link('relatorios/revisao','Revisar '+c.name,{supplier:c.id},'button secondary')).join('')}</div></div>`)}${panel('Relatório executivo','Planejado',`<div class="pad"><p>Resultado do período, evolução, impacto confirmado e decisões para a liderança.</p><div class="note spaced">Modelo planejado. Impacto em estoque, produção e resultado financeiro depende de dados confirmados pelo cliente.</div></div>`)}${[['Dossiê do processo','Marcos, decisões e resultado final de cada importação.'],['Revisão de rota ou agente','Comparáveis, desvios e pauta com o parceiro.'],['Revisão semanal','Compromissos, intervenções e decisões da semana.']].map(([name,desc])=>panel(name,'Planejado',`<div class="pad"><p>${desc}</p><small class="spaced">Ainda sem geração nesta prévia.</small></div>`)).join('')}</div><div class="spaced">${panel('Versões salvas neste navegador','Snapshots locais da análise; nenhuma distribuição automática.',savedReports.length?savedReports.map(r=>`<div class="row"><div>${link('relatorios/versao/'+r.id,`Revisão · ${company(r.supplier).name}`)}<small>${esc(r.createdLabel)} · ${esc(r.periodLabel)} · ${r.operations.length} casos</small></div>${link('relatorios/versao/'+r.id,'Abrir versão')}</div>`).join(''):'<div class="pad muted">Prepare uma revisão e salve a versão após ajustar a pauta.</div>')}</div>`;}
let currentReport=null;
function reportData(){const id=params.get('supplier')||'east';return {supplier:id,operations:filtered({supplier:id}).map(o=>({...o})),periodLabel:periodText(),params:params.toString(),cutoff:D.cutoff,createdLabel:new Date().toLocaleString('pt-BR'),notes:'Confirmar os registros faltantes antes de fechar a avaliação. Revisar os compromissos de prontidão e a qualidade da primeira versão documental com o fornecedor.'};}
function reportView(saved){const r=saved||reportData(),c=company(r.supplier);if(saved){params=new URLSearchParams(r.params);normalizePeriod(params);}currentReport=r;scope=r.operations;const a=D.metric('ready',scope),b=D.metric('docs',scope),p=D.metric('port',scope),q=D.metric('quantity',scope),cond=D.metric('condition',scope);return heading('Revisão de fornecedor',saved?'Versão datada salva neste navegador.':'Revise o recorte e a pauta antes de salvar uma versão.',(saved?'':action('Salvar versão local','save-report','','button'))+action('Exportar HTML','export-report')+action('Imprimir / PDF','print'),link('relatorios','‹ Relatórios',{},'back'))+`<article class="report panel" id="report-document"><div class="cover"><img src="assets/centrix.svg" alt="Freitas Centrix"><div class="overline">Aurora Indústria · Revisão de fornecimento</div><h1>${c.name}</h1><p>${r.periodLabel} · Corte em ${date(r.cutoff)} 2026<br>Base: compromisso de prontidão no período · ${scope.length} embarques distintos.<br>${r.params.includes('route=')||r.params.includes('agent=')||r.params.includes('variant=')?'Recorte adicional: '+esc(reportFilterText(r))+'<br>':''}Preparado em ${esc(r.createdLabel)} · ${saved?'Versão preservada':'Prévia para revisão'}</p><small class="spaced">Dados e evidências demonstrativos. Não representa avaliação real deste parceiro.</small></div><div class="report-section"><h2>O que esta base mostra</h2><p class="summary">${scope.length?`A prontidão foi cumprida em <b>${a.good} de ${a.eligible.length}</b> confirmações. A documentação exigiu correção em <b>${b.eligible.length-b.good} de ${b.eligible.length}</b> checklists. Na cadeia logística, <b>${p.eligible.length-p.good} de ${p.eligible.length}</b> chegadas ao porto ocorreram após o primeiro ETA.`:'Não há operações elegíveis neste recorte. Altere os filtros antes de preparar a revisão.'}</p><p class="muted spaced">Atrasos de transporte não são atribuídos automaticamente ao exportador. Os registros não comprovam efeito em estoque, produção ou vendas.</p>${metrics(['ready','docs','quantity','condition'],scope)}</div><div class="report-section"><h2>Evolução e limites</h2>${table(['Compromisso','Prontidão no prazo','Porto no prazo','Base'],['06','07','08'].map((m,i)=>{const ops=scope.filter(o=>o.readyPlan.slice(5,7)===m),x=D.metric('ready',ops),y=D.metric('port',ops);return `<tr><td>${['Junho','Julho','Agosto'][i]}</td><td>${x.good}/${x.eligible.length}</td><td>${y.good}/${y.eligible.length}</td><td>${ops.length} operações</td></tr>`}).join(''))}<p class="muted spaced">Coortes pequenas com variantes diferentes e operações abertas em agosto. ${q.excluded.length} casos sem quantidade recebida; ${cond.excluded.length} sem inspeção. Ausência de registro não equivale a qualidade de 100%.</p></div><div class="report-section"><h2>Valores documentados</h2>${metrics(['freight','cargo','port','final'],scope)}<small>Frete internacional contratado e valor comercial da mercadoria são montantes distintos, em USD. Taxas, tributos e frete terrestre não compõem o total de frete apresentado.</small></div><div class="report-section"><h2>Pauta para a conversa</h2><ul class="agenda"><li>Revisar ${a.eligible.length-a.good} compromissos de prontidão não cumpridos e suas evidências.</li><li>Repassar ${b.eligible.length-b.good} correções documentais, sem inferir efeito no transporte.</li><li>Apurar ${q.eligible.length-q.good} recebimento(s) parcial(is) e ${cond.eligible.length-cond.good} inspeção(ões) com avaria.</li><li>Confirmar os registros faltantes antes de estabelecer metas ou comparar parceiros.</li></ul><label for="report-notes"><h3 class="spaced">Anotações da revisão</h3></label>${saved?`<p class="spaced">${esc(r.notes).replace(/\n/g,'<br>')}</p>`:`<textarea id="report-notes">${esc(r.notes)}</textarea><small>As anotações entram na versão salva; não são enviadas ao fornecedor.</small>`}</div><div class="report-section"><h2>Base de casos</h2>${operationsTable(scope)}</div><div class="report-section"><h2>Fontes e definições preservadas</h2><p>PO e compromisso original; confirmação de prontidão; checklist documental; proposta aceita; tracking e gate out; comprovante e inspeção de recebimento; fatura e conferência. Todos são registros demonstrativos.</p><small class="spaced">Pontualidade = realizado até compromisso original entre casos com os dois marcos. Quantidade e condição têm denominadores próprios. Banco produtivo, Configurações e distribuição de relatórios não integrados nesta prévia.</small></div></article>`;}
function reportFilterText(r){const q=new URLSearchParams(r.params);return [q.get('route')?routeName(route(q.get('route'))):'',q.get('agent')?agent(q.get('agent')).name:'',q.get('variant')?(q.get('variant')==='direto'?'Serviço direto':'Via Singapura'):''].filter(Boolean).join(' · ');}
function mapView(){return heading('Navegação da Inteligência','Uma base compartilhada para investigar padrões e preparar decisões.')+`<div class="map-grid">${[['Performance',[['performance','Prazos e etapas']]],['Parceiros',[['fornecedores','Fornecedores'],['agentes','Agentes de carga']]],['Rotas e locais',[['rotas','Rotas e variantes'],['locais','Portos e demais locais']]],['Relatórios',[['relatorios/revisao','Revisão de fornecedor'],['relatorios','Executivo e outros modelos']]],['Assistentes',[['assistentes/biblioteca','Biblioteca de análises'],['assistentes/conectar','Conectar sua IA']]]].map(([name,items])=>`<section class="panel map-column"><h2>${name}</h2>${items.map(([path,label])=>link(path,label)).join('')}</section>`).join('')}</div><div class="spaced">${panel('Percurso para investigar um desvio','Comece pela mercadoria e aprofunde a cadeia sem perder o recorte.',`<div class="pad map-path">${[['fornecedores/east/resumo','Fornecedor'],['fornecedores/east/entregas','Entregas'],['rotas/ningbo/etapas','Rota e trechos'],['locais/itajai/resumo','Local / porto'],['agentes/alpha/resumo','Agente']].map(([path,label],i)=>(i?'<span>→</span>':'')+link(path,label,{supplier:'east'},'')).join('')}</div>`)}</div><div class="grid-two spaced">${panel('Radar','Módulo próprio, fora de Inteligência.',`<div class="pad">${link('radar','Ver posição no produto')}<p class="muted spaced">Mercado, riscos e oportunidades. Alertas têm trabalho separado.</p></div>`)}${panel('Configurações','Identidade e preferências existentes.',`<div class="pad"><p>Empresas com papéis, rotas com locais e agentes. A análise reutiliza essas identidades; integração entre as prévias ainda pendente.</p><a class="link" href="/portal/preferencias" target="_blank" rel="noopener">Abrir Configurações ↗</a></div>`)}</div>`;}
function method(){return heading('Fontes e definições','O que cada número mede e onde termina sua cobertura.')+`<div class="note">Aurora Indústria · 12 operações demonstrativas · Compromissos de prontidão de junho a agosto de 2026 · Corte em 13/09/2026. Data prevista nunca é contada como evento realizado.</div><div class="definition-list spaced">${Object.entries(D.metrics).map(([key,m])=>`<article class="panel"><h2>${dataLabel(m.label,key)}</h2><p>${m.definition}</p><small class="spaced">Fonte demonstrativa: ${m.source}</small></article>`).join('')}</div><div class="note spaced">Cadastros: snapshot das identidades de Configurações de 13/09 (v2), conferido nesta sessão. Singapura, coleta Nordwerk e complementos dos corredores Shanghai/Hamburgo existem somente neste cenário. Não há leitura de API, compartilhamento de localStorage ou sincronização do cadastro entre as prévias. Operações DEMO são novas e não substituem os exemplos de outras sessões.</div>`;}
function openDrawer(title,sub,html){closeDataHelp();const d=$('#drawer');if(!d.open)lastFocus=document.activeElement;d.innerHTML=`<header class="drawer-head"><div><h2 id="drawer-title">${title}</h2><small>${sub}</small></div><button autofocus class="close" data-action="close" aria-label="Fechar detalhe">×</button></header><div class="drawer-body">${html}</div>`;if(!d.open)d.showModal();d.scrollTop=0;}
function closeDrawer(){closeDataHelp();if($('#drawer').open)$('#drawer').close();if(lastFocus?.isConnected)lastFocus.focus();}
function metricDrawer(key,ops=scope,onlyBad=false){metricKey=key;metricOps=ops;const a=D.metric(key,ops),shown=onlyBad&&a.m.ok?a.eligible.filter(o=>!a.m.ok(o)):a.eligible;const total=a.m.amount?(a.eligible.length?money(a.total):'Sem valor disponível'):a.eligible.length?`${a.good} ÷ ${a.eligible.length} = ${a.rate}%`:'Sem registros elegíveis';openDrawer(dataLabel(a.m.label,key),`${periodText()} · Corte em 13 set 2026 · ${ops.length} casos na base`,`<p>${a.m.definition}</p><div class="source"><h2>${total}</h2><p>Fonte: ${a.m.source} · Registros demonstrativos.</p><small>${a.eligible.length} elegíveis de ${ops.length} · ${a.excluded.length} excluídos por falta de base</small></div>${a.m.ok?`<div class="actions">${action(onlyBad?'Mostrar todos os elegíveis':'Somente desvios',onlyBad?'metric-all':'metric-bad',key)}</div>`:''}<h3>${onlyBad?'Casos com desvio':'Registros elegíveis'} (${shown.length})</h3>${shown.map(o=>`<div class="row"><div>${link('casos/'+o.id,o.po)}<small>${o.id} · ${company(o.supplier).name}</small><p>${esc(a.m.value(o))}</p>${a.m.ok?pill(a.m.ok(o)?'Atende à definição':'Desvio observado',a.m.ok(o)?'good':'warn'):''}</div>${action('Evidência','sources',o.id,'text-button')}</div>`).join('')||'<p>Nenhum registro nesta seleção.</p>'}<h3>Fora do denominador (${a.excluded.length})</h3>${a.excluded.map(o=>`<div class="row"><div>${link('casos/'+o.id,o.po)}<p>${esc(a.m.value(o))}</p></div>${action('Fonte / lacuna','sources',o.id,'text-button')}</div>`).join('')||(ops.length?'<p>Todos os casos têm os campos necessários para esta métrica.</p>':'<p>Não há operações neste recorte.</p>')}`);}
function stageDrawer(id){const s=[...D.stages,...D.connectionStages].find(x=>x.id===id),base=D.connectionStages.includes(s)?scope.filter(o=>o.variant==='conexao'):scope,e=base.filter(o=>o[s.from]&&o[s.to]),missing=base.filter(o=>!o[s.from]||!o[s.to]);openDrawer(dataLabel(s.label,"stages"),`${periodText()} · Dias corridos · ${e.length}/${base.length} com dois marcos`,`<p>Intervalo realizado por operação. Fonte: ${s.source}, demonstrativa. O previsto é o compromisso deste trecho, não um SLA homologado para toda a empresa.</p>${table(['Caso','Previsto','Realizado','Desvio'],e.map(o=>{const duration=D.days(o[s.from],o[s.to]);return `<tr><td>${link('casos/'+o.id,o.po)}<small>${date(o[s.from])} → ${date(o[s.to])}</small></td><td>${s.plan(o)} d</td><td>${duration} d</td><td>${Math.max(0,duration-s.plan(o))} d</td></tr>`}).join(''))}<h3>Sem intervalo completo (${missing.length})</h3>${missing.map(o=>`<div class="row"><div>${link('casos/'+o.id,o.po)}<p>${o[s.from]?`Entrada em ${date(o[s.from])}; saída não confirmada. Idade no corte: ${D.days(o[s.from],D.cutoff)} d.`:'Marco inicial não informado.'}</p></div></div>`).join('')||'<p>Todos os intervalos estão completos.</p>'}<div class="note spaced">O intervalo localiza o desvio, mas não determina sua causa ou responsável. Etapas abertas não entram como tempo realizado.</div>`);}
function sourceDrawer(id){const o=D.operations.find(x=>x.id===id);openDrawer(`Fontes · ${o.po}`,`${o.id} · Evidências demonstrativas · Corte em 13/09/2026`,[
 ['PO e compromisso original',`DOC-${o.id}-PO`,`${o.sku} · ${o.ordered} un. Prontidão prometida em ${date(o.readyPlan)}; entrega final comprometida em ${date(o.finalPlan)}.`,true],
 ['Confirmação de prontidão',`EVT-${o.id}-READY`,o.ready?`Mensagem do exportador confirma material pronto em ${date(o.ready)}.`:'Confirmação de prontidão não registrada. Não inferir essa data a partir da coleta.',!!o.ready],
 ['Checklist documental',`DOC-${o.id}-CHECK`,D.metrics.docs.value(o)+(o.docs==='corrigida'?'. Quantidade de volumes da packing list corrigida pelo exportador. Efeito no transporte não apurado.':''),!!o.docs],
 ['Proposta aceita',`COT-${o.id}`,`${route(o.route).equipment}; ${o.variant==='conexao'?'via Singapura':'serviço direto'}; frete internacional ${money(o.freight)}. Trânsito previsto: ${o.transitPlan} dias. Primeiro ETA: ${date(o.arrivePlan)}.`,true],
 ['Eventos de transporte',`EVT-${o.id}-TRACK`,`Coleta ${date(o.collect)}; saída ${date(o.depart)}; chegada ${date(o.arrive)}; gate out ${date(o.gate)}. ${o.arrive?'Eventos realizados.':'Chegada atual prevista: '+date(o.arriveForecast)+'. Previsão não é evento.'}`,!!o.depart],
 ['Recebimento e inspeção',`DOC-${o.id}-RECEB`,`${D.metrics.quantity.value(o)}. ${D.metrics.condition.value(o)}. ${o.condition==='avaria'?'Responsabilidade pela avaria não apurada.':''}`,o.received!==null||!!o.condition],
 ['Commercial invoice',`DOC-${o.id}-CI`,D.metrics.cargo.value(o),o.cargoValue!==null]
 ].map(([name,ref,text,exists])=>`<article class="source"><h3>${dataLabel(name,{"PO e compromisso original":"quantity","Confirmação de prontidão":"ready","Checklist documental":"docs","Proposta aceita":"freight","Eventos de transporte":"port","Recebimento e inspeção":"quantity","Commercial invoice":"cargo"}[name])}${name==="Recebimento e inspeção"?dataHelp("condition")+dataHelp("final"):""}</h3>${pill(exists?'Registro demonstrativo disponível':'Fonte ausente',exists?'':'warn')}<p>${esc(text)}</p><small>${ref} · ${exists?'Extrato de cenário fictício; nenhum original comercial anexado.':'Referência reservada; documento não disponível.'}</small></article>`).join('')+`<div class="actions spaced">${link('casos/'+o.id,'Abrir caso completo')}${action('Auditoria','audit',id)}</div>`);}
function auditDrawer(id){const o=D.operations.find(x=>x.id===id);openDrawer(`Auditoria · ${o.po}`,`${o.id} · Conferência demonstrativa`, `<h3>${dataLabel("Auditoria de frete","audit")}</h3><p>${D.metrics.audit.value(o)}</p><div class="source"><b>Proposta aceita COT-${o.id}</b><p>Frete internacional: ${money(o.freight)} · USD · ${route(o.route).equipment}.</p>${['conforme','divergencia'].includes(o.audit)?`<p>Fatura FAT-${o.id}: frete internacional ${money(o.freight)}. Mesmo valor e escopo do frete aceito.</p>`:'<p>Fatura e escopo sem conferência concluída. Este caso não entra como conforme.</p>'}${o.audit==='divergencia'?'<p>Taxas de origem contratadas: USD 250; cobradas: USD 445. Diferença de USD 195 = Documentation Fee USD 45 + taxa não prevista USD 150.</p><p>Comparação fundamentada; justificativa do emissor ainda não recebida. Valor recuperado não confirmado.</p>':''}</div><h3>${dataLabel("Auditoria de performance","cause")}</h3><p>Primeiro ETA ${date(o.arrivePlan)} · ${o.arrive?'chegada realizada '+date(o.arrive):'chegada prevista '+date(o.arriveForecast)}.</p><p>${o.arrive?`Desvio observado de ${Math.max(0,D.days(o.arrivePlan,o.arrive))} dias. Causa do transporte não apurada.`:'Sem conclusão enquanto a chegada não estiver confirmada.'}</p><div class="note">Não há envio de contestação, cobrança de créditos ou integração com o módulo de Auditoria nesta prévia. Os registros acima explicam a análise do agente.</div><div class="actions spaced">${action('Fontes da operação','sources',id)}${link('agentes/'+o.agent+'/auditoria','Abrir histórico do agente')}</div>`);}
function identity(kind,id){let title='',html='';if(kind==='identity'){const c=company(id);title=c.name;html=`<p>${c.legal}</p><p>Papéis: ${c.roles.join(' e ')}. Nesta análise: fornecedor/exportador.</p><p>${c.city}, ${c.country} · Contato ${c.contact}.</p><p>${c.notes}</p>`}else if(kind==='agent-identity'){const a=agent(id);title=a.name;html=`<p>Contato: ${a.contact}</p><p>${a.preferred?'Preferido pela empresa.':'Sem preferência da empresa.'} Preferência não é qualidade e não compõe as métricas.</p>`}else if(kind==='route-identity'){const r=route(id);title=routeName(r);html=`<p>${r.mode} · ${r.equipment}</p><p>Identidade do corredor: ${loc(r.from).code} → ${loc(r.to).code}.</p><p>Agente preferido no cadastro: ${agent(r.agent).name}.</p><p>${id==='ningbo'?'Coleta Eastbridge e entrega Aurora reutilizam os IDs da prévia atual de Configurações.':'Coleta e entrega que não constam no cadastro foram acrescentadas somente a este cenário analítico.'} Nenhum cadastro foi alterado.</p>`}else{const l=loc(id);title=l.name;html=`<p>${l.type} · ${l.code||'Sem código externo'} · ${l.country}</p><p>${l.extension?'Local acrescentado apenas na base demonstrativa para completar o percurso; não gravado em Configurações.':'Identidade reutilizada do catálogo de Configurações.'}</p>`}openDrawer(title,'Identidade cadastral · somente leitura',html+`<div class="note spaced">Snapshot da prévia de Configurações de 13/09 (v2), conferido nesta sessão. Nenhuma atualização de cadastro nesta sessão. O desempenho vem de outra base demonstrativa, com cobertura própria.</div><p><a class="link" href="/portal/preferencias" target="_blank" rel="noopener">Abrir Configurações ↗</a></p>`);}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4000);}
function render(){if($('#drawer').open)closeDrawer();const raw=location.hash.slice(1).split('?');pagePath=raw[0]||'fornecedores';params=new URLSearchParams(raw[1]||'');normalizePeriod(params);for(const [key,valid] of [['supplier',D.companies.map(x=>x.id)],['agent',D.agents.map(x=>x.id)],['route',D.routes.map(x=>x.id)],['variant',['direto','conexao']]])if(params.has(key)&&!valid.includes(params.get(key)))params.delete(key);scope=filtered();const [section,id,tab]=pagePath.split('/');moduleNav();$('#context').innerHTML=['mapa','metodo','radar'].includes(section)||id==='versao'?'':commonContext();let html='';if(section==='fornecedores')html=id?supplierDetail(id,tab):supplierList();else if(section==='rotas')html=id?routeDetail(id,tab):routesList();else if(section==='locais')html=id?localDetail(id,tab):localList();else if(section==='agentes')html=id?agentDetail(id,tab):agentsList();else if(section==='casos')html=caseDetail(id);else if(section==='performance')html=performance();else if(section==='assistentes')html=assistantsView(id,tab);else if(section==='relatorios')html=id==='revisao'?reportView():id==='versao'?(savedReports.find(x=>x.id===tab)?reportView(savedReports.find(x=>x.id===tab)):empty('Versão não encontrada neste navegador')):reportLibrary();else if(section==='mapa')html=mapView();else if(section==='metodo')html=method();else if(section==='radar')html=heading('Radar','Módulo próprio no menu principal, fora de Inteligência.')+panel('Mercado, riscos e oportunidades','Nesta prévia, apenas a posição na navegação. Experiência trabalhada separadamente.',`<div class="pad"><p>Mercado de fretes, riscos logísticos, oportunidades de contratação, agentes e parceiros e abastecimento quando houver dados.</p><div class="actions spaced"><a class="button secondary" href="/portal/radar" target="_blank" rel="noopener">Abrir Radar ↗</a>${link('mapa','Voltar ao mapa do módulo',{},'button secondary')}${link('performance','Abrir Performance',{},'button')}</div></div>`);else html=empty('Página não encontrada');$('#page').innerHTML=html;moduleNav();if(section==='assistentes'){const nav=$('#module-nav'),active=nav.querySelector('.active');if(active&&nav.scrollWidth>nav.clientWidth)nav.scrollLeft=active.offsetLeft-nav.offsetLeft-12;}const selection=viewSelections.get(location.hash)||{};if($('#search')&&selection.search){$('#search').value=selection.search;$('#supplier-results').innerHTML=supplierRows(selection.search);}if($('#delivery-status')&&selection.deliveryStatus){$('#delivery-status').value=selection.deliveryStatus;$('#delivery-rows').innerHTML=operationsTable(scope.filter(o=>selection.deliveryStatus==='all'||(selection.deliveryStatus==='done'?!!o.final:!o.final)));}document.title=(document.querySelector('.heading h1')?.textContent||'Inteligência')+' · Centrix';}
document.addEventListener('change',e=>{if(e.target.id==='period'){if(e.target.value==='custom'){editPeriod();}else{$('#period-editor').hidden=true;location.hash=url(pagePath,{period:e.target.value,start:null,end:null});}}else if(e.target.matches('[data-filter]')){const key=e.target.dataset.filter,section={supplier:'fornecedores',route:'rotas',agent:'agentes'}[key];if(pagePath.startsWith(section+'/'))location.hash=url(section+(e.target.value?'/'+e.target.value+'/resumo':''),{[key]:null,variant:key==='route'?null:params.get('variant')});else location.hash=url(pagePath,{[key]:e.target.value});}else if(e.target.id==='variant')location.hash=url(pagePath,{variant:e.target.value});else if(e.target.id==='delivery-status'){viewSelections.set(location.hash,{deliveryStatus:e.target.value});$('#delivery-rows').innerHTML=operationsTable(scope.filter(o=>e.target.value==='all'||(e.target.value==='done'?!!o.final:!o.final)));}});
document.addEventListener('submit',e=>{if(e.target.id!=='period-editor')return;e.preventDefault();const start=$('#period-start').value,end=$('#period-end').value;if(!periodRange({period:'custom',start,end}).valid){$('#period-error').textContent='Escolha datas válidas: o início deve ser anterior ou igual ao fim, até '+fullDate(D.cutoff)+'.';$('#period-error').hidden=false;return;}location.hash=url(pagePath,{period:'custom',start,end});$('#period-editor').hidden=true;$('#period-error').hidden=true;$('#period').value='custom';});
document.addEventListener('input',e=>{if(e.target.id==='search'){viewSelections.set(location.hash,{search:e.target.value});$('#supplier-results').innerHTML=supplierRows(e.target.value);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b){const a=b.dataset.action,id=b.dataset.id;if(a==='close')closeDrawer();else if(a==='metric')metricDrawer(id);else if(a==='metric-bad')metricDrawer(id,metricOps,true);else if(a==='metric-all')metricDrawer(id,metricOps,false);else if(a==='stage')stageDrawer(id);else if(a==='sources')sourceDrawer(id);else if(a==='audit')auditDrawer(id);else if(a.includes('identity'))identity(a,id);else if(a==='local-moves')location.hash=url('locais/'+id+'/movimentacoes');else if(a==='filters'){$('#filters-panel').hidden=!$('#filters-panel').hidden;b.setAttribute('aria-expanded',String(!$('#filters-panel').hidden));}else if(a==='remove-filter')location.hash=url(pagePath,{[id]:null});else if(a==='edit-period'){editPeriod();}else if(a==='cancel-period'){$('#period-editor').hidden=true;$('#period').value=params.get('period')||'year';}else if(a==='clear')location.hash='#'+pagePath;else if(a==='month'){const ops=scope.filter(o=>o.readyPlan.slice(5,7)===periodMonths[id]);openDrawer('Evolução · '+({jun:'Junho 2026',jul:'Julho 2026',ago:'Agosto 2026'}[id]),'Coorte por compromisso original de prontidão',`<p>${ops.length} operações neste mês do recorte atual. Compare as duas dimensões por seus denominadores.</p>${operationsTable(ops)}`);}else if(a==='back'){if(history.length>1)history.back();else location.hash=url('fornecedores');}else if(a==='print')window.print();else if(a==='save-report'){currentReport.notes=$('#report-notes').value;const r={...currentReport,id:'rev-'+Date.now()};try{localStorage.setItem('centrix-intelligence-reports-v1',JSON.stringify([...savedReports,r]));savedReports.push(r);location.hash='#relatorios/versao/'+r.id;toast('Versão salva neste navegador.');}catch{toast('Não foi possível salvar no navegador. Exporte o HTML para preservar a revisão.');}}else if(a==='export-report')await exportReport();return;}
 const anchor=e.target.closest('a[href^="#"]');if(anchor&&anchor.getAttribute('href')==='#main'){e.preventDefault();$('#main').focus();return;}if(anchor&&$('#drawer').open)closeDrawer();});
const positions=new Map();let previousHash=location.hash;
window.addEventListener('hashchange',()=>{positions.set(previousHash,window.scrollY);previousHash=location.hash;render();window.scrollTo(0,positions.get(location.hash)||0);});
$('#drawer').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});
async function exportReport(){const article=$('#report-document').cloneNode(true);article.querySelector(".data-help-notes")?.remove();dataHelpReportNotes(article);article.querySelectorAll("[data-help]").forEach(b=>b.remove());const notes=article.querySelector('textarea');if(notes){const p=document.createElement('p');p.textContent=$('#report-notes').value;notes.replaceWith(p);}article.querySelectorAll('button').forEach(b=>{const div=document.createElement('div');div.className=b.className;div.innerHTML=b.innerHTML;div.querySelector('.metric-link')?.remove();b.replaceWith(div)});article.querySelectorAll('a[href^="#"]').forEach(a=>a.href=location.origin+'/portal/inteligencia'+a.getAttribute('href'));try{const fontData=async path=>{const blob=await fetch(path).then(r=>r.blob());return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});};const [css,logo,newBlack,source]=await Promise.all([fetch('style.css').then(r=>r.text()),fetch('assets/centrix.svg').then(r=>r.text()),fontData('assets/NewBlack-Medium.woff2'),fontData('assets/SourceSans3.ttf')]);article.querySelector('img').src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(logo);const fontless=css.replace(/@font-face\{[^}]*\}/g,'');const blob=new Blob([`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Revisão de fornecedor · Centrix</title><style>${fontless}@font-face{font-family:NewBlack;src:url('${newBlack}')}@font-face{font-family:Source;src:url('${source}');font-weight:200 900}body{padding:30px}.report{background:white}</style><body>${article.outerHTML}</body></html>`],{type:'text/html;charset=utf-8'});const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`Centrix-revisao-${currentReport.supplier}-2026-09-13.html`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('Relatório exportado com recorte, definições e casos.');}catch{toast('Exportação indisponível. Tente novamente ou use Imprimir / PDF.');}}
render();
